+test('signal cancels queued tasks and rejects them with the abort reason', async t => {
+	const controller = new AbortController();
+	const limit = pLimit({concurrency: 1, signal: controller.signal});
+	const reason = new Error('cancelled');
+
+	const runningPromise = limit(() => delay(100));
+	const pendingPromiseOne = limit(() => delay(10));
+	const pendingPromiseTwo = limit(() => delay(10));
+
+	await Promise.resolve();
+	t.is(limit.pendingCount, 2);
+
+	controller.abort(reason);
+	t.is(limit.pendingCount, 0);
+
+	await t.throwsAsync(pendingPromiseOne, {is: reason});
+	await t.throwsAsync(pendingPromiseTwo, {is: reason});
+	await t.notThrowsAsync(runningPromise);
+});
+
+test('signal that is already aborted rejects new tasks immediately without running them', async t => {
+	const controller = new AbortController();
+	const reason = new Error('already cancelled');
+	controller.abort(reason);
+
+	const limit = pLimit({concurrency: 1, signal: controller.signal});
+	let ran = false;
+
+	await t.throwsAsync(limit(() => {
+		ran = true;
+	}), {is: reason});
+
+	t.is(ran, false);
+	t.is(limit.pendingCount, 0);
+	t.is(limit.activeCount, 0);
+});
+
+test('throws on invalid signal argument', t => {
+	t.throws(() => {
+		pLimit({concurrency: 1, signal: {}});
+	});
+});
+
